-- B3/B4: explicit read projections and booking reschedule contract.
create or replace function public.reschedule_booking(p_booking_id uuid,p_new_scheduled_at timestamptz) returns void language plpgsql security definer set search_path=public,pg_temp as $function$ declare v_booking public.bookings%rowtype; v_role text; v_duration integer; v_local timestamp; begin if p_new_scheduled_at is null or p_new_scheduled_at<=now() then raise exception 'A future scheduled time is required'; end if; select role into v_role from public.profiles where id=auth.uid(); select * into v_booking from public.bookings where id=p_booking_id for update; if not found then raise exception 'Booking not found'; end if; if v_role='admin' or v_booking.user_id=auth.uid() or exists(select 1 from public.gurubas g where g.id=v_booking.guruba_id and g.user_id=auth.uid()) then null; else raise exception 'Access denied'; end if; if v_booking.status not in ('pending','confirmed') then raise exception 'Only pending or confirmed bookings can be rescheduled'; end if; select duration_minutes into v_duration from public.services where id=v_booking.service_id; if coalesce(v_duration,0)<=0 then raise exception 'Booking service has no fixed duration'; end if; v_local=p_new_scheduled_at at time zone 'Asia/Kathmandu'; if extract(minute from v_local)::integer not in (0,30) or extract(second from v_local)<>0 then raise exception 'Booking time must be on a 30-minute boundary'; end if; perform pg_advisory_xact_lock(hashtextextended('booking-slot:'||v_booking.guruba_id::text||':'||v_local::date::text,0)); if not exists(select 1 from public.guruba_availability a where a.guruba_id=v_booking.guruba_id and a.day_of_week=extract(dow from v_local)::integer and v_local::time>=a.start_time and (v_local::time+make_interval(mins=>v_duration))<=a.end_time) then raise exception 'Selected time is outside the Guruba availability'; end if; if exists(select 1 from public.bookings b join public.services bs on bs.id=b.service_id where b.id<>p_booking_id and b.guruba_id=v_booking.guruba_id and b.status in ('pending','confirmed','awaiting_client_confirmation') and b.scheduled_at is not null and v_local<(b.scheduled_at at time zone 'Asia/Kathmandu')+make_interval(mins=>greatest(coalesce(bs.duration_minutes,60),30)+30) and v_local+make_interval(mins=>v_duration)>(b.scheduled_at at time zone 'Asia/Kathmandu')) then raise exception 'That time is no longer available'; end if; update public.bookings set scheduled_at=p_new_scheduled_at,proposed_time=null,confirmation_deadline=null where id=p_booking_id; end; $function$;
revoke execute on function public.reschedule_booking(uuid,timestamptz) from public,anon; grant execute on function public.reschedule_booking(uuid,timestamptz) to authenticated;
create or replace function public.get_my_profile() returns table(id uuid,full_name text,role text,avatar_url text,gotra_id uuid,city text,languages text[],latitude double precision,longitude double precision,address text) language sql stable security invoker set search_path=public,pg_temp as $$ select p.id,p.full_name,p.role,p.avatar_url,p.gotra_id,p.city,p.languages,p.latitude,p.longitude,p.address from public.profiles p where p.id=auth.uid(); $$;
revoke execute on function public.get_my_profile() from public; grant execute on function public.get_my_profile() to authenticated;
create or replace function public.get_public_gurubas() returns table(guruba_id uuid,user_id uuid,full_name text,avatar_url text,bio text,years_experience integer,rating numeric,location text,specialties text[],languages text[],guruba_type text,review_count integer,is_verified boolean,gotra_id uuid) language sql stable security invoker set search_path=public,pg_temp as $$ select g.id,g.user_id,p.full_name,p.avatar_url,g.bio,g.years_experience,g.rating,g.location,g.specialties,g.languages,g.guruba_type,g.review_count,g.is_verified,p.gotra_id from public.gurubas g join public.profiles p on p.id=g.user_id where g.is_verified=true; $$;
revoke execute on function public.get_public_gurubas() from public; grant execute on function public.get_public_gurubas() to anon,authenticated;
